def epsilon_closure(states, eps):
    # eps[q]: q에서 ε-전이 한 번으로 가는 상태 집합
    closure = set(states)
    stack = list(states)
    while stack:
        q = stack.pop()
        for r in eps.get(q, ()):
            if r not in closure:  # 처음 도달한 상태만 확장
                closure.add(r)
                stack.append(r)
    return closure

def accepts(word, start, finals, eps, delta):
    cur = epsilon_closure({start}, eps)
    for c in word:
        # 입력 c를 소비한 뒤 다시 ε-closure
        nxt = set()
        for q in cur:
            nxt |= delta.get((q, c), set())
        cur = epsilon_closure(nxt, eps)
    return bool(cur & finals)
